// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    __InvMutHandleStub savings;

    function setUp() public {
        savings = new __InvMutHandleStub();
        c = new MStableYieldSource(ISavingsContractV2(address(savings)));
    }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor, address to) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        amount1 = bound(amount1, 2, type(uint128).max);
        amount2 = bound(amount2, 2, type(uint128).max);

        vm.startPrank(actor);
        c.supplyTokenTo(amount1, to);
        c.supplyTokenTo(amount2, to);
        vm.stopPrank();

        // General rule: after supplying to `to` (twice, but true for any number of supplies),
        // c.imBalances[to] equals the TOTAL credits the savings contract issued for `to`'s supplies.
        assertTrue(c.imBalances(to) == savings.totalCredits(), "imBalances must equal total credits issued for the recipient");
    }
}

contract __InvMutHandleStub {
    uint256 public totalCredits;

    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function exchangeRate() external pure returns (uint256) { return 1e18; }
    function depositSavings(uint256 _amount) external returns (uint256 creditsIssued) {
        creditsIssued = _amount / 2;
        totalCredits += creditsIssued;
    }
    receive() external payable {}
    fallback() external payable {}
}
